"use client";

import { loadFont } from "@remotion/google-fonts/BricolageGrotesque";
import { useId } from "react";
import { AbsoluteFill, Easing, interpolate, spring } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_CHART_DATA,
  type OffTheChartsElementId,
  offTheChartsTimeline,
} from "./timeline";

const { fontFamily: sans } = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface OffTheChartsDatum {
  label: string;
  value: number;
}

export interface OffTheChartsProps {
  data?: OffTheChartsDatum[];
  accentIndex?: number;
  target?: number;
  max?: number;
  unit?: string;
  targetLabel?: string;
  value?: string;
  caption?: string;
  accent?: string;
  /** Text color of the figure, target label and highlighted column; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the copy. Load it yourself; Bricolage Grotesque by default. */
  fontFamily?: string;
  /** Frames the highlighted bar climbs and presses on the frame before it breaks through. */
  push?: number;
  /** Corner radius of the bars, in px at 720p. */
  radius?: number;
  grain?: boolean;
  /** Size of the chart and figure, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches the chart frame, the labels, the target, the
   * bars, the highlighted bar's press and break, and the figure, by the ids
   * in `./timeline`. Frames on the scene timeline, after `delay` and
   * `speed`.
   */
  timing?: Timing<OffTheChartsElementId>;
}

const DEFAULT_DATA: OffTheChartsDatum[] = DEFAULT_CHART_DATA;

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const PUSH = Easing.bezier(0.45, 0, 0.3, 1);

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    bar: "#46464D",
    frame: "rgba(243,242,239,0.42)",
    grid: "rgba(243,242,239,0.1)",
    target: "rgba(243,242,239,0.7)",
    heatTop: "#ffe2c4",
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    bar: "#CFCDC6",
    frame: "rgba(18,18,20,0.42)",
    grid: "rgba(18,18,20,0.1)",
    target: "rgba(18,18,20,0.72)",
    heatTop: "#ffbf8f",
    grain: 0.045,
  },
} as const;

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={29}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

const lerp = (a: number, b: number, k: number) => a + (b - a) * k;

function barPath(x: number, bottom: number, w: number, h: number, r0: number) {
  const r = Math.max(0, Math.min(r0, h / 2, w / 2));
  const top = bottom - h;
  return `M${x} ${bottom} L${x} ${top + r} Q${x} ${top} ${x + r} ${top} L${x + w - r} ${top} Q${x + w} ${top} ${x + w} ${top + r} L${x + w} ${bottom} Z`;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function OffTheCharts(props: OffTheChartsProps) {
  const {
    data = DEFAULT_DATA,
    accentIndex,
    target = 100,
    max = 150,
    unit = "%",
    targetLabel = "Target",
    value,
    caption = "of the Q4 target",
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = sans,
    radius = 4,
    grain = true,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    offTheChartsTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const frameEl = tl.get("frame");
  const gridEl = tl.get("grid");
  const catsEl = tl.get("categories");
  const topEl = tl.get("top");
  const targetEl = tl.get("target");
  const barsEl = tl.get("bars");
  const rightEl = tl.get("right");
  const targetLabelEl = tl.get("target-label");
  const pressEl = tl.get("press");
  const strainEl = tl.get("strain");
  const breakEl = tl.get("break");
  const heroEl = tl.get("hero");
  const captionEl = tl.get("caption");
  const u = height / 720;
  const p = THEMES[theme];
  const fg = ink ?? p.fg;
  const bg =
    background === "transparent" ? "transparent" : (background ?? p.bg);
  const riseAt = pressEl.start;
  const pressAt = pressEl.end;
  const breakAt = breakEl.start;
  const heatId = `heat${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;

  const rows = data.length > 0 ? data : DEFAULT_DATA;
  const n = rows.length;
  const ai =
    accentIndex !== undefined && accentIndex >= 0 && accentIndex < n
      ? accentIndex
      : n - 1;
  const peak = Math.max(rows[ai].value, max * 1.02);
  const heroText = value ?? `${rows[ai].value}${unit}`;

  const boxL = width * 0.15;
  const boxR = width * 0.62;
  const bottom = height * 0.84;
  const ceiling = height * 0.13;
  const px = (bottom - ceiling) / peak;
  const boxT = bottom - max * px;
  const slot = (boxR - boxL) / (n + 0.6);
  const bw = Math.min(slot * 0.6, 96 * u);
  const barX = (i: number) => boxL + slot * (i + 0.8) - bw / 2;
  const aX = barX(ai);
  const sw = Math.max(1, 1.25 * u);

  const frameIn = interpolate(t, [frameEl.start, frameEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const gridIn = interpolate(t, [gridEl.start, gridEl.end], [0, 1], CLAMP);
  const targetDraw = interpolate(t, [targetEl.start, targetEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const targetLab = interpolate(
    t,
    [targetLabelEl.start, targetLabelEl.end],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_OUT,
    },
  );

  const rest = rows.map((d, i) => {
    if (i === ai) return 0;
    const order = i < ai ? i : i - 1;
    return (
      d.value *
      interpolate(
        t,
        [
          barsEl.start + order * barsEl.beat("stagger"),
          barsEl.start + order * barsEl.beat("stagger") + barsEl.beat("rise"),
        ],
        [0, 1],
        {
          ...CLAMP,
          easing: EASE_OUT,
        },
      )
    );
  });

  const accentV = rows[ai].value;
  const breaks = accentV > max;
  const pressTo = breaks ? max : accentV;
  const barAt = (f: number) => {
    const phaseA = interpolate(f, [riseAt, pressAt], [0, pressTo], {
      ...CLAMP,
      easing: PUSH,
    });
    const tension = breaks
      ? interpolate(f, [strainEl.start, strainEl.end], [0, 7 * u], {
          ...CLAMP,
          easing: Easing.bezier(0.55, 0, 1, 0.45),
        })
      : 0;
    const release = spring({
      frame: f - breakAt,
      fps,
      config: { damping: 15, stiffness: 120, mass: 0.8 },
    });
    const broken = breaks && f >= breakAt;
    const aH = broken
      ? lerp(max * px + 7 * u, accentV * px, release)
      : phaseA * px + tension;
    return { tension, broken, aH };
  };
  const { tension, broken, aH } = barAt(t);
  const aVal = aH / px;
  // The counter rides the bar's top the whole time it shows. Placed by `top`,
  // layout rounded its baseline to whole pixels, so the climb stepped unevenly;
  // layout holds it at the bar's foot and the climb is a transform.
  const counterMoving =
    Math.abs(barAt(t + 1).aH - aH) > 1e-3 ||
    Math.abs(aH - barAt(t - 1).aH) > 1e-3;

  const snap = breaks
    ? spring({
        frame: t - breakAt,
        fps,
        config: { damping: 11, stiffness: 260, mass: 0.5 },
      })
    : 0;
  const pad = 12 * u;
  const half = bw / 2 + pad * snap;
  const cx = aX + bw / 2;

  const slashIn = broken
    ? interpolate(snap, [0, 0.7], [0.4, 1], { ...CLAMP, easing: EASE_OUT })
    : 0;
  const slashLen = 16 * u;
  const slashDx = slashLen * 0.36;

  const hitAt = heroEl.start;
  const heroAt = (f: number) =>
    spring({
      frame: f - hitAt,
      fps,
      config: { damping: 16, stiffness: 150, mass: 0.7 },
    });
  // The hero rides the bar's top, and the bar settles on a long spring tail.
  // Layout rounds a baseline to whole pixels, so riding it by `top` clicked
  // the figure down pixel by pixel; layout holds the settled top instead and
  // the ride is a transform.
  const restH = (breaks ? accentV : pressTo) * px;
  const heroLift = (f: number) =>
    restH - barAt(f).aH + (1 - heroAt(f)) * 18 * u;
  const lift = heroLift(t);
  const heroMoving =
    Math.abs(heroLift(t + 1) - lift) > 1e-3 ||
    Math.abs(lift - heroLift(t - 1)) > 1e-3;
  const heroO = interpolate(t, [hitAt, heroEl.end], [0, 1], CLAMP);
  const cap = interpolate(t, [captionEl.start, captionEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const counterO =
    interpolate(
      t,
      [riseAt + pressEl.beat("countFrom"), riseAt + pressEl.beat("count")],
      [0, 1],
      CLAMP,
    ) *
    interpolate(
      t,
      [hitAt + heroEl.beat("counterFrom"), hitAt + heroEl.beat("counterTo")],
      [1, 0],
      CLAMP,
    );

  const ty = bottom - target * px;
  const boxStop = Math.min(0.9, max / Math.max(accentV, max));
  const gridVals = [0, max / 3, (2 * max) / 3, max];
  const fmt = (v: number) => `${Math.round(v)}${v === 0 ? "" : unit}`;

  const leftW = lerp(0, boxR - boxL, frameIn);
  const upH = lerp(0, bottom - boxT, frameIn);
  const topDraw = interpolate(t, [topEl.start, topEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const rightDraw = interpolate(t, [rightEl.start, rightEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        <svg
          width={width}
          height={height}
          style={{ position: "absolute", inset: 0 }}
          aria-hidden
        >
          <defs>
            {/* gradients.sh "fluted": in-chart blue, overheating past the frame. */}
            <linearGradient
              id={heatId}
              gradientUnits="userSpaceOnUse"
              x1={0}
              y1={bottom}
              x2={0}
              y2={bottom - accentV * px}
            >
              <stop offset={0} stopColor="#1d2a8f" />
              <stop offset={boxStop * 0.55} stopColor={accent} />
              <stop offset={boxStop} stopColor="#2f7bff" />
              <stop offset={boxStop + 0.012} stopColor="#ff7a3d" />
              <stop offset={1} stopColor={p.heatTop} />
            </linearGradient>
          </defs>
          {gridVals.slice(1, -1).map((g) => (
            <line
              key={`g-${g}`}
              x1={boxL}
              x2={boxR}
              y1={bottom - g * px}
              y2={bottom - g * px}
              stroke={p.grid}
              strokeWidth={sw}
              opacity={gridIn}
            />
          ))}

          <line
            x1={boxL}
            x2={boxL}
            y1={bottom}
            y2={bottom - upH}
            stroke={p.frame}
            strokeWidth={sw}
          />
          {rightDraw > 0 && (
            <line
              x1={boxR}
              x2={boxR}
              y1={boxT}
              y2={lerp(boxT, bottom, rightDraw)}
              stroke={p.frame}
              strokeWidth={sw}
            />
          )}
          {topDraw > 0 && !broken && tension > 0 && (
            <polyline
              points={`${boxL},${boxT} ${aX},${boxT - tension} ${aX + bw},${boxT - tension} ${boxR},${boxT}`}
              fill="none"
              stroke={p.frame}
              strokeWidth={sw}
              strokeLinejoin="round"
            />
          )}
          {topDraw > 0 && (broken || tension <= 0) && (
            <>
              <line
                x1={boxL}
                x2={broken ? cx - half : lerp(boxL, boxR, topDraw)}
                y1={boxT}
                y2={boxT}
                stroke={p.frame}
                strokeWidth={sw}
              />
              {broken && (
                <line
                  x1={cx + half}
                  x2={lerp(boxL, boxR, topDraw)}
                  y1={boxT}
                  y2={boxT}
                  stroke={p.frame}
                  strokeWidth={sw}
                />
              )}
            </>
          )}

          {rows.map((d, i) => {
            if (i === ai) return null;
            const h = rest[i] * px;
            if (h <= 0.01) return null;
            return (
              <path
                key={`b-${d.label}`}
                d={barPath(barX(i), bottom, bw, h, radius * u)}
                fill={p.bar}
              />
            );
          })}

          <line
            x1={boxL}
            x2={lerp(boxL, boxR, targetDraw)}
            y1={ty}
            y2={ty}
            stroke={p.target}
            strokeWidth={Math.max(1, 1.5 * u)}
            strokeDasharray={`${7 * u} ${6 * u}`}
          />

          {aH > 0.01 && (
            <path
              d={barPath(aX, bottom, bw, aH, radius * u)}
              fill={`url(#${heatId})`}
            />
          )}

          {broken &&
            [cx - half, cx + half].map((x) => (
              <line
                key={`s-${x > cx ? "r" : "l"}`}
                x1={x - slashDx * slashIn}
                y1={boxT + (slashLen / 2) * slashIn}
                x2={x + slashDx * slashIn}
                y2={boxT - (slashLen / 2) * slashIn}
                stroke={fg}
                strokeWidth={Math.max(1, 1.6 * u)}
                strokeLinecap="round"
                opacity={slashIn}
              />
            ))}

          <line
            x1={boxL}
            x2={boxL + leftW}
            y1={bottom}
            y2={bottom}
            stroke={p.frame}
            strokeWidth={Math.max(1, 1.5 * u)}
          />
        </svg>

        {gridVals.map((g) => (
          <div
            key={`gl-${g}`}
            style={{
              position: "absolute",
              left: boxL - 150 * u,
              width: 150 * u - 14 * u,
              top: bottom - g * px - 10 * u,
              height: 20 * u,
              lineHeight: `${20 * u}px`,
              textAlign: "right",
              fontFamily,
              fontWeight: 400,
              fontSize: 16 * u,
              fontVariantNumeric: "tabular-nums",
              color: p.muted,
              opacity: gridIn,
            }}
          >
            {fmt(g)}
          </div>
        ))}

        <div
          style={{
            position: "absolute",
            left: boxR + 14 * u,
            top: ty - 10 * u,
            height: 20 * u,
            lineHeight: `${20 * u}px`,
            fontFamily,
            fontWeight: 500,
            fontSize: 16 * u,
            color: fg,
            opacity: targetLab,
            transform: `translateX(${(1 - targetLab) * -6 * u}px)`,
            whiteSpace: "nowrap",
          }}
        >
          {targetLabel}
        </div>

        {rows.map((d, i) => (
          <div
            key={`c-${d.label}`}
            style={{
              position: "absolute",
              left: barX(i) + bw / 2 - 80 * u,
              width: 160 * u,
              top: bottom + 14 * u,
              textAlign: "center",
              fontFamily,
              fontWeight: i === ai ? 500 : 400,
              fontSize: 16 * u,
              color: i === ai ? fg : p.muted,
              opacity: interpolate(
                t,
                [
                  catsEl.start + i * catsEl.beat("stagger"),
                  catsEl.start +
                    i * catsEl.beat("stagger") +
                    catsEl.beat("fade"),
                ],
                [0, 1],
                CLAMP,
              ),
            }}
          >
            {d.label}
          </div>
        ))}

        <div
          style={{
            position: "absolute",
            left: aX,
            width: bw,
            top: bottom + 10 * u,
            transform:
              aH > 1e-3
                ? `translateY(${-aH}px)${glide(counterMoving)}`
                : undefined,
            textAlign: "center",
            fontFamily,
            fontWeight: 500,
            fontSize: 16 * u,
            letterSpacing: "0",
            fontVariantNumeric: "tabular-nums",
            color: broken ? "#2B1206" : "#FFFFFF",
            opacity:
              counterO * interpolate(aH, [36 * u, 48 * u], [0, 1], CLAMP),
            whiteSpace: "nowrap",
          }}
        >
          {`${Math.round(aVal)}${unit}`}
        </div>

        <div
          style={{
            position: "absolute",
            left: aX + bw + 30 * u,
            top: bottom - restH - 10 * u,
            opacity: heroO,
            transform: `translateY(${lift}px)${glide(heroMoving)}`,
          }}
        >
          <div
            style={{
              fontFamily,
              fontWeight: 400,
              fontSize: 150 * u,
              lineHeight: 0.86,
              letterSpacing: "-0.04em",
              color: fg,
              fontVariantNumeric: "tabular-nums",
              whiteSpace: "nowrap",
            }}
          >
            {heroText}
          </div>
          <div
            style={{
              marginTop: 16 * u,
              fontFamily,
              fontWeight: 400,
              fontSize: 24 * u,
              letterSpacing: "-0.01em",
              color: p.muted,
              opacity: cap,
              transform: `translateY(${(1 - cap) * 8 * u}px)`,
              whiteSpace: "nowrap",
            }}
          >
            {caption}
          </div>
        </div>
      </ScaleLayer>

      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 85% 85% at 50% 50%, transparent 64%, ${bg} 100%)`,
          opacity: 0.5,
        }}
      />
      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The chart frame drawing in (sides, grid, top), the category labels, the
// target line and its label, the other bars rising, then the highlighted
// bar climbing, straining against the frame's top, breaking through, and
// the figure landing with its caption. Frames on the 30 fps scene timeline,
// after `delay` and `speed`. The ids are public: a saved `timing` prop
// refers to them.

export type OffTheChartsElementId =
  | "frame"
  | "grid"
  | "categories"
  | "top"
  | "target"
  | "bars"
  | "right"
  | "target-label"
  | "press"
  | "strain"
  | "break"
  | "hero"
  | "caption";

export interface OffTheChartsTimingProps {
  data?: object[];
  push?: number;
}

export const DEFAULT_CHART_DATA = [
  { label: "Q1", value: 58 },
  { label: "Q2", value: 74 },
  { label: "Q3", value: 86 },
  { label: "Q4", value: 260 },
];

const RISE = 40;
const PRESS = 66;
const BREAK = 69;

// `categories` fades the labels in, one every `stagger` frames, each over
// `fade`; `bars` raises the other bars the same way (`stagger`, `rise`).
// `press` climbs the highlighted bar to the frame's top over its length,
// its counter fading in from `countFrom` to `count`. `strain` bends the
// frame; `break` springs the bar through from its start. `hero` fades the
// figure in over its length, the counter fading out from `counterFrom` to
// `counterTo` around its start. Strain, break, hero and caption each follow
// the one before; strain follows the press.
export const offTheChartsTimeline = defineTimeline<
  OffTheChartsElementId,
  OffTheChartsTimingProps
>(({ data = DEFAULT_CHART_DATA, push = PRESS - RISE }) => {
  const n = data.length > 0 ? data.length : DEFAULT_CHART_DATA.length;
  const others = Math.max(0, n - 1);
  const pressAt = RISE + push;
  const breakAt = pressAt + (BREAK - PRESS);
  const hitAt = breakAt + 14;
  const elements: TimelineElement<OffTheChartsElementId>[] = [
    { id: "frame", lane: "Chart", label: "Frame", start: 0, length: 14 },
    { id: "grid", lane: "Chart", label: "Grid", start: 6, length: 14 },
    {
      id: "categories",
      lane: "Labels",
      label: "Categories",
      start: 6,
      length: (n - 1) * 2 + 12,
      beats: { stagger: 2, fade: 12 },
    },
    { id: "top", lane: "Chart", label: "Top edge", start: 8, length: 14 },
    { id: "target", lane: "Target", label: "Target", start: 10, length: 20 },
    {
      id: "bars",
      lane: "Bars",
      label: "Bars",
      start: 18,
      length: Math.max(0, others - 1) * 4 + 22,
      beats: { stagger: 4, rise: 22 },
    },
    { id: "right", lane: "Chart", label: "Right edge", start: 18, length: 12 },
    {
      id: "target-label",
      lane: "Target",
      label: "Target label",
      start: 24,
      length: 12,
    },
    {
      id: "press",
      lane: "Highlight",
      label: "Press",
      start: RISE,
      length: push,
      beats: { countFrom: 4, count: 10 },
    },
    {
      id: "strain",
      lane: "Highlight",
      label: "Strain",
      start: pressAt,
      length: BREAK - PRESS,
      follows: "press",
    },
    {
      id: "break",
      lane: "Highlight",
      label: "Break through",
      start: breakAt,
      length: hitAt - breakAt,
      follows: "strain",
    },
    {
      id: "hero",
      lane: "Figure",
      label: "Figure",
      start: hitAt,
      length: 7,
      follows: "break",
      beats: { counterFrom: -4, counterTo: 2 },
    },
    {
      id: "caption",
      lane: "Figure",
      label: "Caption",
      start: hitAt + 8,
      length: 16,
      follows: "hero",
    },
  ];
  return elements.sort((a, b) => a.start - b.start);
});
